import useAxiosLarge from "../../hook/useAxiosLarge/useAxiosLarge";
import icons from "../../constants/Icons";

import "./Week.css";

const Week = ({ city, temp }) => {
  const count = [0, 1, 2, 3, 4];
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);

  const tomorrowDay = String(tomorrow.getDate()).padStart(2, "0");
  const { dataL } = useAxiosLarge({ city: city });
  console.log(today + 1);

  const firstMatch = dataL?.list.find(
    (elm) => elm.dt_txt.split(" ")[0].split("-")[2] === tomorrowDay
  );

  const kelvinToCelsius = (num) => {
    return num - 273.15;
  };
  const kelvinToFar = (num) => {
    return ((num - 273.15) * 9) / 5 + 32;
  };

  return (
    <div className="mainWeek">
      <div className="eachDay">
        <p className="">{firstMatch?.dt_txt.split(" ")[0].slice(5)}</p>
        <div className="tempWeek">
          {temp === "C" ? (
            <p className="temperature">{Math.trunc(kelvinToCelsius(firstMatch?.main.temp))} °C</p>
          ) : (
            <p className="temperature">{Math.trunc(kelvinToFar(firstMatch?.main.temp))} °F</p>
          )}
          {icons.map((elm) =>
            elm.weather === firstMatch?.weather[0].main ? (
              <img src={elm.icon} className="icon" alt="weatherIcon" />
            ) : null
          )}
        </div>
      </div>
    </div>
  );
};

export default Week;
